from pathlib import Path
from tempfile import TemporaryDirectory
from audit_morphology_support import _build_input
from charter_context import make_pairs
import hashlib,re,json
root=Path(__file__).parent; source=root/'ittb-train.conllu';raw=source.read_bytes();assert hashlib.sha256(raw).hexdigest()=='7a8ed5d4a3391e918213ffa988f0930364e009e97a4ae4c3c820837fb3cfe29a';rows={}
with TemporaryDirectory() as temp:
 files={n:open(Path(temp)/f'book{n}.conllu','w') for n in (2,3,4)}
 for block in raw.decode().split('\n\n'):
  m=re.search(r'^# sent_id = train-s(\d+)$',block,re.M)
  if not m:continue
  i=int(m[1]);n=2 if 105<=i<=5657 else 3 if 5658<=i<=13519 else 4 if 16810<=i<=22775 else None
  if n:files[n].write(block+'\n\n')
 for f in files.values():f.close()
 for n in (2,3,4):
  occ,sites,docs=_build_input(Path(temp)/f'book{n}.conllu');modes={}
  for mode in ('all','internal','internal_same_morph','terminal_same_stem_case'):
   pairs,support=make_pairs(sites,mode,66103,frozenset());modes[mode]={'pairs':len(pairs),'right_disagreements':sum(a.after!=b.after for a,b in pairs),'support':support}
  rows[str(n)]={'modes':modes}
print(json.dumps(rows,indent=2))
